# compute exact tilings for test/demos with 2x2 full square and 3-of-4 Ls
T={(0,1),(0,2),(0,4),(0,5),(1,0),(1,1),(1,2),(1,3),(1,4),(1,5),(2,1),(2,2),(2,4),(3,2),(3,3),(3,4)}
# create placements in each adjacent 2x2 block
placements=[]
for r in range(6):
 for c in range(6):
  cellset={(r,c),(r,c+1),(r+1,c),(r+1,c+1)}
  for missing in [None,*list(cellset)]:
   s=cellset if missing is None else cellset-{missing}
   if s<=T: placements.append((s, (r,c,missing)))
def rec(remaining, chosen):
 if not remaining:
  yield chosen; return
 x=min(remaining)
 for s, typ in placements:
  if x in s and s<=remaining:
   yield from rec(remaining-s,chosen+[typ])
sol=list(rec(T,[]))
len(sol), sol[:5]
